'use strict';
const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto'),{spawn}=require('node:child_process');
const manifest=require('../config/avatar-studio/avatar-qa-models.json');const root=path.resolve(process.cwd(),'.artifacts/models/avatar-qa');
const POSE_HELPERS=Object.freeze([{id:'mediapipe-person-detector-postprocess',filename:'mp_persondet.py',url:'https://raw.githubusercontent.com/opencv/opencv_zoo/main/models/person_detection_mediapipe/mp_persondet.py',expectedSha256:'e530a8ebc3c218376d5dd1c13aa8ed39a850fac4dbcd6928144746b33477b9c7',expectedByteSize:148509,license:'Apache-2.0',upstream:'OpenCV Zoo',upstreamRef:'47534e27c9851bb1128ccc0102f1145e27f23f98'},{id:'mediapipe-pose-postprocess',filename:'mp_pose.py',url:'https://raw.githubusercontent.com/opencv/opencv_zoo/main/models/pose_estimation_mediapipe/mp_pose.py',expectedSha256:'7e1953d1fb848c64fd3b44277e615e273e7fb2f325f7633eb9c1e32948d45e67',expectedByteSize:9521,license:'Apache-2.0',upstream:'OpenCV Zoo',upstreamRef:'47534e27c9851bb1128ccc0102f1145e27f23f98'}]);
async function download(url){const response=await fetch(url,{redirect:'follow'});if(!response.ok)throw new Error(`model download failed: HTTP ${response.status}`);return Buffer.from(await response.arrayBuffer());}
function command(bin,args) {
  return new Promise((resolve,reject) => {
    const child=spawn(bin,args,{stdio:'inherit'});
    child.on('error',reject);
    child.on('exit',(code) => {
      if(code===0) resolve(); else reject(new Error(`${bin} exited ${code}`));
    });
  });
}
async function main(){if(manifest.schemaVersion!==1)throw new Error('unsupported Avatar QA model manifest');await fs.mkdir(root,{recursive:true,mode:0o700});let previous={installed:[]};try{previous=JSON.parse(await fs.readFile(path.join(root,'manifest.json'),'utf8'));}catch{}const venv=path.join(root,'venv-3.13');const python=path.join(venv,'bin','python');try{await fs.access(python);}catch{await command('python3.13',['-m','venv',venv]);}try{await command(python,['-c','import cv2']);}catch{await command(python,['-m','pip','install','--upgrade','--force-reinstall','opencv-python-headless==4.10.0.84']);}const installed=[];for(const model of [...manifest.models,...POSE_HELPERS]){if(!['MIT','Apache-2.0','BSD-3-Clause'].includes(model.license))throw new Error(`unapproved model license: ${model.id}`);const target=path.join(root,model.filename);let bytes;try{bytes=await fs.readFile(target);}catch{bytes=await download(model.url);if(bytes.length<1024)throw new Error(`model artifact is unexpectedly small: ${model.filename}`);await fs.writeFile(target,bytes,{mode:0o600});}const sha256=crypto.createHash('sha256').update(bytes).digest('hex'), previousSha256=previous.installed?.find((item)=>item.id===model.id)?.sha256;if(model.expectedByteSize&&bytes.length!==model.expectedByteSize)throw new Error(`model byte-size mismatch: ${model.id}`);if(model.expectedSha256&&sha256!==model.expectedSha256)throw new Error(`model SHA-256 mismatch: ${model.id}`);if(previousSha256&&previousSha256!==sha256)throw new Error(`installed model SHA-256 changed: ${model.id}`);installed.push({...model,sha256,byteSize:bytes.length,installedAt:new Date().toISOString(),expectedRuntime:'python3.13 + opencv-python-headless==4.10.0.84'});}await fs.writeFile(path.join(root,'manifest.json'),JSON.stringify({schemaVersion:1,root,installed},null,2)+'\n',{mode:0o600});console.log(`Avatar QA models ready locally: ${installed.map((x)=>x.id).join(', ')}`);}
main().catch((error)=>{console.error(`[AVATAR_QA_BOOTSTRAP_FAILED] ${error.message}`);process.exitCode=1;});
